const samples = ["Leela", 42, true, undefined, null, 10n, Symbol("id"), {}, [], () => 1];

for (const value of samples) {
  console.log(String(typeof value).padEnd(10), "<-", String(value === null ? "null" : value).slice(0, 24));
}

console.log("typeof null      :", typeof null, " <- use `value === null`");
console.log("typeof []        :", typeof []);
console.log("Array.isArray([]):", Array.isArray([]), "<- the reliable check");
console.log("Array.isArray({}):", Array.isArray({}));

const booking = { firstname: "Leela", totalprice: 120 };

// The typo. No error, no warning.
const price = (booking as Record<string, unknown>)["totalPrice"];
console.log("booking.totalPrice ->", price);

// It only breaks HERE, three steps later, blaming the wrong line.
const withTax = (price as number) * 1.2;
console.log("price * 1.2        ->", withTax, "<- NaN, and the typo is nowhere in sight");

let userName: string = "Leela";      // explicit
let visitCount = 0;                  // inferred as number - hover it in an editor

console.log(userName, visitCount);

// Inference is not weaker than an annotation. Both of these are `number`,
// and both refuse a string later.
let explicitAge: number = 30;
let inferredAge = 30;
console.log(typeof explicitAge, typeof inferredAge);

const months: string[] = ["Jan", "Feb", "Mar"];
const years: number[] = [2024, 2025];
const mixed: (string | number)[] = ["Jan", 2024];

console.log(months.length, years.length, mixed);

// Because TypeScript knows these are strings, it knows what methods exist.
console.log(months.map((m) => m.toUpperCase()));

// years.map((y) => y.toUpperCase());   // uncomment -> tsc: toUpperCase does not
                                        // exist on type 'number'

function add(a: number, b: number): number {
  return a + b;
}

// async functions return a Promise, so the annotation says so - the shape you
// have been reading since week 1.
async function fetchName(id: number): Promise<string> {
  return `user-${id}`;
}

console.log(add(2, 3));
console.log(await fetchName(7));

// add("2", "3");    // uncomment -> tsc: Argument of type 'string' is not
                     // assignable to parameter of type 'number'

class Student {
  readonly name: string;
  private score: number;

  constructor(name: string, score: number) {
    this.name = name;
    this.score = score;
  }

  passed(): boolean {
    return this.score >= 40;
  }
}

const learner = new Student("Leela", 72);
console.log(learner.name, "passed?", learner.passed());

// learner.score;        // uncomment -> tsc: 'score' is private
// learner.name = "Bob"; // uncomment -> tsc: 'name' is read-only

enum StatusFamily {
  Success = 200,
  Redirect = 300,
  ClientError = 400,
  ServerError = 500,
}

console.log(StatusFamily.ClientError);              // 400
console.log(StatusFamily[400]);                     // "ClientError" - both directions

function familyOf(code: number): string {
  const base = Math.floor(code / 100) * 100;
  return StatusFamily[base] ?? "unknown";
}

for (const code of [201, 302, 404, 500, 999]) {
  console.log(code, "->", familyOf(code));
}

// Write a deliberate type error to a scratch file, then run the compiler on it.
const bad = `const total: number = "not a number";
export {};
`;
await Deno.writeTextFile("scratch-type-error.ts", bad);

const check = new Deno.Command("npx", {
  args: ["tsc", "--noEmit", "--strict", "scratch-type-error.ts"],
  cwd: "..",
  stdout: "piped",
  stderr: "piped",
});
const out = await check.output();
console.log(new TextDecoder().decode(out.stdout).trim() || "(no output)");
console.log("exit code:", out.code, out.code === 0 ? "" : "<- the build would fail here");

await Deno.remove("scratch-type-error.ts");

const parsed: any = JSON.parse('{"firstname":"Leela"}');

// Both compile. One is a typo. `any` cannot tell you which.
console.log("correct:", parsed.firstname);
console.log("typo   :", parsed.firstName, "<- undefined, and tsc said nothing");

// The fix is to describe the shape you expect.
type Booking = { firstname: string };
const typed = JSON.parse('{"firstname":"Leela"}') as Booking;
console.log("typed  :", typed.firstname);
// typed.firstName;   // uncomment -> tsc catches it

// This repo's actual compiler settings.
