const tsconfig = await Deno.readTextFile(`${REPO_ROOT}/tsconfig.json`);
console.log(tsconfig);

import { REPO_ROOT as ROOT_B } from "../_shared/deno-helpers.ts";

const helper = await Deno.readTextFile(`${ROOT_B}/week7/generated/api-helpers.ts`);
